/// V1: `(**(code **)(local + 4))(local)`: the state-function pointer stored in the local data
fn call_state(e: &mut Engine, a: u32, p: u32) -> LResult<()> {
    let _ = p;
    match a {
        0x10e80 => { mcRockST_Waiting_In(e)?; }
        0x10ee0 => { mcRockST_Waiting_Execute(e)?; }
        0x10f78 => { mcRockST_Creation_In(e)?; }
        0x11088 => { mcRockST_Creation_Execute(e)?; }
        0x11120 => { mcRockST_Thrown_In(e)?; }
        0x11568 => { mcRockST_Thrown_Execute(e)?; }
        _ => panic!("call through a non-state pointer {a:#x}"),
    }
    Ok(())
}
